// src/components/CarCard.jsx
import React from 'react';
import { Link } from 'react-router-dom';

export default function CarCard({ car }) {
  const isAvailable = car.status === 'available';

  return (
    <div className="border rounded-lg overflow-hidden shadow-sm bg-white flex flex-col justify-between">
      <div>
        <img
          src={car.image_url || 'https://placehold.co/600x400?text=Car+Image'}
          alt={`${car.brand} ${car.model}`}
          className="w-full h-48 object-cover"
        />
        <div className="p-4">
          <div className="flex justify-between items-start mb-2">
            <h3 className="font-bold text-lg">{car.brand} {car.model}</h3>
            <span className={`text-xs px-2 py-1 rounded-full font-medium ${
              isAvailable ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
            }`}>
              {isAvailable ? 'พร้อมเช่า' : 'ไม่ว่าง'}
            </span>
          </div>
          <p className="text-sm text-gray-500 mb-3">ประเภท: {car.car_type || 'ทั่วไป'}</p>
          <p className="text-blue-600 font-bold text-xl">
            {Number(car.price_per_day).toLocaleString()} <span className="text-sm font-normal text-gray-600">บาท / วัน</span>
          </p>
        </div>
      </div>

      <div className="p-4 pt-0">
        <Link
          to={`/cars/${car.id}`}
          className="block w-full text-center bg-slate-800 text-white py-2 rounded hover:bg-slate-700"
        >
          ดูรายละเอียด
        </Link>
      </div>
    </div>
  );
}
